'use strict';

// MODULES //

var tape = require( 'tape' );
var objectKeys = require( '@stdlib/utils/keys' );
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var isArray = require( '@stdlib/assert/is-array' );
var DATA = require( './../data/data.json' );
var packages = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof packages, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if not provided a string', function test( t ) {
	var values;
	var i;

	values = [
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			packages( value );
		};
	}
});

tape( 'the function returns package metadata', function test( t ) {
	var expected;
	var actual;
	var keys;
	var i;

	keys = objectKeys( DATA );
	for ( i = 0; i < keys.length; i++ ) {
		expected = DATA[ keys[i] ];
		actual = packages( keys[i] );
		t.deepEqual( actual, expected, 'returns expected value for '+keys[i] );
	}
	t.end();
});

tape( 'returned metadata has the expected shape', function test( t ) {
	var out;

	out = packages( '@stdlib/math/base/special/sin' );
	t.strictEqual( isPlainObject( out ), true, 'returns an object' );
	t.strictEqual( isString( out.description ), true, 'has description' );
	t.strictEqual( isString( out.alias ), true, 'has alias' );
	t.strictEqual( isString( out.type ), true, 'has type' );
	t.strictEqual( isArray( out.related ), true, 'has related' );
	t.strictEqual( isBoolean( out.hasCliTool ), true, 'has hasCliTool' );
	t.strictEqual( isBoolean( out.hasNativeAddon ), true, 'has hasNativeAddon' );
	t.strictEqual( isBoolean( out.hasWasm ), true, 'has hasWasm' );
	t.end();
});

tape( 'the function returns `null` if provided an unrecognized package name', function test( t ) {
	var values;
	var i;

	values = [
		'adfkaljdfdsafs',
		'adklfadjflajdslfjalsdf',
		'adflkajdlkfjasdlkfjsadlkfjlasdjflsdjfla'
	];
	for ( i = 0; i < values.length; i++ ) {
		t.strictEqual( packages( values[ i ] ), null, 'returns expected value' );
	}
	t.end();
});
